draw(circle((1, i), 0.1));

draw(circle((3, i), 0.1));

draw(circle((5, i), 0.1));

draw(circle((7, i), 0.1));

draw(circle((9, i), 0.1));

draw(circle((11, i), 0.1));

draw(circle((13, i), 0.1));

draw(circle((15, i), 0.1));
}

pen target = red + linewidth(2);

draw((-0.8, -1)--(0.8, -1));
draw((1.2, -1)--(2.8, -1));
draw((3.2, -1)--(4.8, -1));
draw((5.2, -1)--(6.8, -1));
